import copy,math,pathlib,time,os
def snapshot():
    return dict(boot_id=pathlib.Path('/proc/sys/kernel/random/boot_id').read_text().strip(),monotonic=time.monotonic(),stat=pathlib.Path('/proc/stat').read_text(),softirqs=pathlib.Path('/proc/softirqs').read_text(),hz=os.sysconf('SC_CLK_TCK'))
def _parse(sample):
    rows=[line.split() for line in sample['stat'].splitlines() if line.split() and (line.split()[0]=='cpu' or line.split()[0][3:].isdigit() and line.startswith('cpu'))]
    aggregate=[r for r in rows if r[0]=='cpu']
    if len(aggregate)!=1 or len(aggregate[0])!=11:raise ValueError('ten aggregate CPU counters required')
    counters=list(map(int,aggregate[0][1:]))
    if any(n<0 for n in counters):raise ValueError('unsigned cumulative counters required')
    cpus={r[0] for r in rows if r[0]!='cpu'}
    lines=sample['softirqs'].splitlines();header=lines[0].split()
    if len(header)!=len(set(header)) or {s.lower() for s in header}!=cpus:raise ValueError('CPU topology differs across non-atomic files')
    vectors={}
    for line in lines[1:]:
        if not line.strip():continue
        name,values=line.split(':',1);name=name.strip();counts=list(map(int,values.split()))
        if name in vectors or len(counts)!=len(header) or any(n<0 for n in counts):raise ValueError('invalid softirq vector')
        vectors[name]=sum(counts)
    return counters,cpus,vectors
def compare(before,after):
    elapsed=after['monotonic']-before['monotonic']
    if not isinstance(elapsed,(int,float)) or not math.isfinite(elapsed) or elapsed<=0:raise ValueError('positive finite monotonic interval required')
    if not before['boot_id'] or before['boot_id']!=after['boot_id'] or before['hz']!=after['hz'] or before['hz']<=0:raise ValueError('new boot or clock unit')
    a,cpus,av=_parse(before);b,nextcpus,bv=_parse(after)
    if cpus!=nextcpus or av.keys()!=bv.keys():raise ValueError('topology changed; resample')
    delta=[y-x for x,y in zip(a,b)]
    if any(v<0 for i,v in enumerate(delta) if i!=4) or any(bv[k]<av[k] for k in av):raise ValueError('counter reset; resample')
    warnings=[]
    if delta[4]<0:delta[4]=0;warnings.append('iowait_decreased_clamped')
    total=sum(delta[:8])
    if total<=0:raise ValueError('no CPU time interval')
    return dict(irq_seconds=delta[5]/before['hz'],softirq_seconds=delta[6]/before['hz'],irq_ratio=delta[5]/total,softirq_ratio=delta[6]/total,softirq_events_per_second={k:(bv[k]-av[k])/elapsed for k in av},warnings=warnings)
